-- [~] FUNCTION tax
DROP FUNCTION IF EXISTS `tax`;

-- [~] PROCEDURE mode_proc
DROP PROCEDURE IF EXISTS `mode_proc`;

-- [-] PROCEDURE old_proc
DROP PROCEDURE IF EXISTS `old_proc`;

-- [~] FUNCTION tax
-- DEFINER 없이 생성합니다 — 실행한 사용자가 DEFINER 가 됩니다
SET @OLD_SQL_MODE = @@SQL_MODE, SQL_MODE = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION';
DELIMITER ;;
CREATE FUNCTION `tax`(a decimal(10,2)) RETURNS decimal(10,2)
    DETERMINISTIC
    COMMENT '세금 8%'
BEGIN RETURN a * 0.08; END;;
DELIMITER ;
SET SQL_MODE = @OLD_SQL_MODE;

-- [~] PROCEDURE mode_proc
-- DEFINER 없이 생성합니다 — 실행한 사용자가 DEFINER 가 됩니다
SET @OLD_SQL_MODE = @@SQL_MODE, SQL_MODE = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION';
DELIMITER ;;
CREATE PROCEDURE `mode_proc`()
BEGIN
  SELECT 1;
END;;
DELIMITER ;
SET SQL_MODE = @OLD_SQL_MODE;

-- [+] FUNCTION net
-- DEFINER 없이 생성합니다 — 실행한 사용자가 DEFINER 가 됩니다
SET @OLD_SQL_MODE = @@SQL_MODE, SQL_MODE = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION';
DELIMITER ;;
CREATE FUNCTION `net`(a decimal(10,2)) RETURNS decimal(10,2)
    DETERMINISTIC
RETURN a - tax(a);;
DELIMITER ;
SET SQL_MODE = @OLD_SQL_MODE;

-- [+] PROCEDURE list_orders
-- DEFINER 없이 생성합니다 — 실행한 사용자가 DEFINER 가 됩니다
SET @OLD_SQL_MODE = @@SQL_MODE, SQL_MODE = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION';
DELIMITER ;;
CREATE PROCEDURE `list_orders`(IN p_status varchar(10))
    READS SQL DATA
    SQL SECURITY INVOKER
    COMMENT '상태별 주문'
BEGIN
  SELECT id, amount FROM orders WHERE status = p_status;
END;;
DELIMITER ;
SET SQL_MODE = @OLD_SQL_MODE;

-- [+] VIEW order_net
-- DEFINER 없이 생성합니다 — 실행한 사용자가 DEFINER 가 됩니다
CREATE OR REPLACE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `order_net` AS select `orders`.`id` AS `id`,`net`(`orders`.`amount`) AS `net` from `orders`;
